class Solution {
public:
    bool check(vector<vector<int>> &graph,vector<int> &colour,int src)
    {
        queue<int> q;
        q.push(src);
        colour[src]=1;
        while(!q.empty())
        {
            int node=q.front();
            q.pop();
            for(auto it:graph[node])
            {
                if(colour[it]==-1)
                {
                    colour[it]=1-colour[node];
                    q.push(it);
                }
                else if(colour[it]==colour[node])
                    return false;
            }
        }
        return true;
    }
    bool isBipartite(vector<vector<int>>& graph) {
        int n=graph.size();
        vector<int> colour(n,-1);
        for(int i=0;i<n;i++)
        {
            if(colour[i]==-1)
            {
                if(!check(graph,colour,i))
                    return false;
            }
        }
        return true;
    }
};

class Solution(object):
    def isBipartite(self, graph):
        """
        :type graph: List[List[int]]
        :rtype: bool
        """
        n = len(graph)
        colors = [0 for _ in range(n)]

        def dfs(cur_node, cur_color):
            colors[cur_node] = cur_color
            for new_node in graph[cur_node]:
                if colors[new_node] == cur_color:
                    return False
                if colors[new_node] == 0 and not dfs(new_node, -cur_color):
                    return False
            return True

        for i in range(n):
            if colors[i] == 0 and not dfs(i, 1):
                return False
        return True
